package com.bankhighlightsearch;

import java.awt.AlphaComposite;
import java.awt.Color;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import java.awt.image.BufferedImage;
import java.util.HashMap;
import java.util.Map;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.SpritePixels;
import net.runelite.api.widgets.WidgetItem;
import net.runelite.api.widgets.ItemQuantityMode;
import net.runelite.client.game.ItemManager;
import net.runelite.client.ui.overlay.WidgetItemOverlay;
import static net.runelite.api.Constants.CLIENT_DEFAULT_ZOOM;

class BankHighlightOverlay extends WidgetItemOverlay
{
	private static final long BLINK_PERIOD_MS = 300;
	private static final long PULSE_PERIOD_MS = 900;

	private final BankHighlightSearchPlugin plugin;
	private final BankHighlightSearchConfig config;
	private final ItemManager itemManager;
	private final Client client;

	private final Map<Long, BufferedImage> glowCache = new HashMap<>();

	@Inject
	BankHighlightOverlay(BankHighlightSearchPlugin plugin, BankHighlightSearchConfig config, ItemManager itemManager, Client client)
	{
		this.plugin = plugin;
		this.config = config;
		this.itemManager = itemManager;
		this.client = client;
		showOnBank();
	}

	@Override
	public void renderItemOverlay(Graphics2D graphics, int itemId, WidgetItem widgetItem)
	{
		if (!plugin.isMatched(itemId))
		{
			return;
		}

		final HighlightStyle style = config.highlightStyle();
		final long sinceSearch = System.currentTimeMillis() - plugin.getSearchTime();
		final int searchDuration = config.searchDuration();
		if (searchDuration > 0 && sinceSearch > searchDuration * 1000L)
		{
			return; // highlight expired
		}
		final int blinkDuration = config.blinkDuration();
		final boolean animating = blinkDuration == 0 || sinceSearch < blinkDuration * 1000L;

		if (style != HighlightStyle.FEATHERED_PULSE && animating && (sinceSearch / BLINK_PERIOD_MS) % 2 == 1)
		{
			return; // off-phase of the blink
		}

		final Rectangle bounds = widgetItem.getCanvasBounds();
		final Color color = config.highlightColor();

		switch (style)
		{
			case ITEM_OUTLINE:
				drawOutline(graphics, itemId, widgetItem, color);
				break;
			case FEATHERED_PULSE:
				if (animating)
				{
					drawGlow(graphics, itemId, widgetItem, color, pulseFeather(sinceSearch));
				}
				else
				{
					drawOutline(graphics, itemId, widgetItem, color);
				}
				break;
			case ITEM_OUTLINE_AND_FILL:
				drawOutline(graphics, itemId, widgetItem, color);
				drawFill(graphics, bounds);
				break;
			case BOX:
				graphics.setColor(color);
				graphics.drawRect(bounds.x, bounds.y, bounds.width - 1, bounds.height - 1);
				break;
			case UNDERLINE:
				final int underlineY = bounds.y + bounds.height + 2;
				graphics.setColor(color);
				graphics.drawLine(bounds.x, underlineY, bounds.x + bounds.width, underlineY);
				break;
			case FILL:
				drawFill(graphics, bounds);
				break;
		}
	}

	private int pulseFeather(long sinceSearch)
	{
		final int min = config.pulseMinFeather();
		final int max = Math.max(min, config.pulseMaxFeather());
		final double phase = (sinceSearch % PULSE_PERIOD_MS) / (double) PULSE_PERIOD_MS;
		final double tri = phase < 0.5 ? phase * 2 : 2 - phase * 2;
		return min + (int) Math.round(tri * (max - min));
	}

	private void drawGlow(Graphics2D graphics, int itemId, WidgetItem widgetItem, Color color, int feather)
	{
		final int quantity = widgetItem.getQuantity();
		// quantity is part of the key because the punch-out mask varies with it
		final long key = ((long) itemId << 36) | ((long) quantity << 4) | feather;
		BufferedImage glow = glowCache.get(key);
		if (glow == null)
		{
			if (glowCache.size() > 512)
			{
				glowCache.clear();
			}
			// real quantity so the outline uses the same stack-model variant the bank
			// renders; getItemOutline never bakes stack-text glyphs (ItemQuantityMode.NEVER)
			final BufferedImage outline = itemManager.getItemOutline(itemId, quantity, color);
			// punch-out mask with the real quantity and STACKABLE mode so the digits land
			// exactly where the bank draws them; DstOut erases those pixels from the glow
			final SpritePixels spritePixels = client.createItemSprite(
				itemId, quantity, 0, 0, ItemQuantityMode.STACKABLE, false, CLIENT_DEFAULT_ZOOM);
			final BufferedImage mask = spritePixels != null ? spritePixels.toBufferedImage() : outline;
			glow = buildGlow(outline, mask, feather);
			glowCache.put(key, glow);
		}
		final Rectangle bounds = widgetItem.getCanvasBounds();
		graphics.drawImage(glow, bounds.x - feather, bounds.y - feather, null);
	}

	private static BufferedImage buildGlow(BufferedImage outline, BufferedImage mask, int feather)
	{
		final BufferedImage img = new BufferedImage(outline.getWidth() + 2 * feather, outline.getHeight() + 2 * feather, BufferedImage.TYPE_INT_ARGB);
		final Graphics2D g = img.createGraphics();
		// stamp the outline in expanding rings with quadratic falloff so the glow
		// dims harder with distance from the item
		for (int d = feather; d >= 1; d--)
		{
			final float f = 1f - (float) (d - 1) / feather;
			final float alpha = 0.6f * f * f;
			g.setComposite(AlphaComposite.getInstance(AlphaComposite.SRC_OVER, alpha));
			for (int dx = -1; dx <= 1; dx++)
			{
				for (int dy = -1; dy <= 1; dy++)
				{
					if (dx != 0 || dy != 0)
					{
						g.drawImage(outline, feather + dx * d, feather + dy * d, null);
					}
				}
			}
		}
		// punch out the item silhouette so the glow never covers the item sprite
		g.setComposite(AlphaComposite.DstOut);
		g.drawImage(mask, feather, feather, null);
		// draw the crisp 1px outline on top at full opacity
		g.setComposite(AlphaComposite.SrcOver);
		g.drawImage(outline, feather, feather, null);
		g.dispose();
		return img;
	}

	void invalidateGlowCache()
	{
		glowCache.clear();
	}

	private void drawOutline(Graphics2D graphics, int itemId, WidgetItem widgetItem, Color color)
	{
		// real quantity so the outline uses the same stack-model variant the bank
		// renders; getItemOutline never bakes stack-text glyphs (ItemQuantityMode.NEVER)
		final BufferedImage outline = itemManager.getItemOutline(itemId, widgetItem.getQuantity(), color);
		final Rectangle bounds = widgetItem.getCanvasBounds();
		graphics.drawImage(outline, bounds.x, bounds.y, null);
	}

	private void drawFill(Graphics2D graphics, Rectangle bounds)
	{
		final Color fill = config.fillColor();
		if (fill.getAlpha() > 0)
		{
			graphics.setColor(fill);
			graphics.fill(bounds);
		}
	}
}

package com.bankhighlightsearch;

import java.awt.Color;
import java.awt.event.InputEvent;
import java.awt.event.KeyEvent;
import net.runelite.client.config.Alpha;
import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.ConfigSection;
import net.runelite.client.config.Keybind;
import net.runelite.client.config.Range;
import net.runelite.client.config.Units;

@ConfigGroup(BankHighlightSearchConfig.GROUP)
public interface BankHighlightSearchConfig extends Config
{
	String GROUP = "bankhighlightsearch";

	@ConfigItem(
		keyName = "searchKeybind",
		name = "Search hotkey",
		description = "Opens the highlight search input while the bank is open",
		position = 0
	)
	default Keybind searchKeybind()
	{
		return new Keybind(KeyEvent.VK_F, InputEvent.CTRL_DOWN_MASK | InputEvent.SHIFT_DOWN_MASK);
	}

	@ConfigItem(
		keyName = "highlightStyle",
		name = "Highlight style",
		description = "How matching items are highlighted",
		position = 1
	)
	default HighlightStyle highlightStyle()
	{
		return HighlightStyle.ITEM_OUTLINE;
	}

	@Alpha
	@ConfigItem(
		keyName = "highlightColor",
		name = "Highlight color",
		description = "Outline color for matching items",
		position = 2
	)
	default Color highlightColor()
	{
		return Color.ORANGE;
	}

	@Alpha
	@ConfigItem(
		keyName = "fillColor",
		name = "Fill color",
		description = "Fill color for the fill styles",
		position = 3
	)
	default Color fillColor()
	{
		return new Color(255, 165, 0, 40);
	}

	@Range(max = 30)
	@Units(Units.SECONDS)
	@ConfigItem(
		keyName = "blinkDuration",
		name = "Blink duration",
		description = "How long highlights blink after a search before turning solid (0 = blink forever)",
		position = 4
	)
	default int blinkDuration()
	{
		return 3;
	}

	@Range(max = 300)
	@Units(Units.SECONDS)
	@ConfigItem(
		keyName = "searchDuration",
		name = "Highlight duration",
		description = "How long highlights stay visible after a search (0 = until next search or bank close)",
		position = 5
	)
	default int searchDuration()
	{
		return 0;
	}

	@ConfigSection(
		name = "Feathered pulse",
		description = "Settings for the feathered pulse highlight style",
		position = 6,
		closedByDefault = true
	)
	String pulseSection = "pulseSection";

	@Range(max = 10)
	@Units(Units.PIXELS)
	@ConfigItem(
		keyName = "pulseMinFeather",
		name = "Pulse min thickness",
		description = "Feathered pulse: feather at the low point of the pulse (0 = bare 1px outline)",
		position = 0,
		section = pulseSection
	)
	default int pulseMinFeather()
	{
		return 0;
	}

	@Range(min = 1, max = 10)
	@Units(Units.PIXELS)
	@ConfigItem(
		keyName = "pulseMaxFeather",
		name = "Pulse max thickness",
		description = "Feathered pulse: outline thickness at the peak of the pulse",
		position = 1,
		section = pulseSection
	)
	default int pulseMaxFeather()
	{
		return 4;
	}

	@ConfigItem(
		keyName = "highlightPlaceholders",
		name = "Highlight placeholders",
		description = "Also highlight bank placeholders whose name matches",
		position = 7
	)
	default boolean highlightPlaceholders()
	{
		return true;
	}

	@ConfigItem(
		keyName = "includeVariations",
		name = "Match variations",
		description = "Also highlight charge/dose variations of matched items",
		position = 8
	)
	default boolean includeVariations()
	{
		return true;
	}
}

package com.bankhighlightsearch;

import com.google.inject.Provides;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.Set;
import java.util.function.Consumer;
import javax.inject.Inject;
import lombok.Getter;
import net.runelite.api.Client;
import net.runelite.api.Item;
import net.runelite.api.ItemComposition;
import net.runelite.api.ItemContainer;
import net.runelite.api.MenuAction;
import net.runelite.api.ScriptID;
import net.runelite.api.events.ItemContainerChanged;
import net.runelite.api.events.MenuEntryAdded;
import net.runelite.api.events.ScriptPostFired;
import net.runelite.api.events.WidgetClosed;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.InventoryID;
import net.runelite.api.gameval.VarClientID;
import net.runelite.api.gameval.VarbitID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.game.ItemManager;
import net.runelite.client.game.ItemVariationMapping;
import net.runelite.client.game.chatbox.ChatboxPanelManager;
import net.runelite.client.game.chatbox.ChatboxTextInput;
import net.runelite.client.input.KeyManager;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.overlay.OverlayManager;
import net.runelite.client.util.HotkeyListener;

@PluginDescriptor(
	name = "Bank Highlight Search",
	description = "Search the bank with a hotkey and highlight matches instead of filtering them out",
	tags = {"bank", "search", "highlight", "find"}
)
public class BankHighlightSearchPlugin extends Plugin
{
	private static final int POTIONSTORE_TAB = 15;

	@Inject
	private Client client;

	@Inject
	private ClientThread clientThread;

	@Inject
	private KeyManager keyManager;

	@Inject
	private OverlayManager overlayManager;

	@Inject
	private ItemManager itemManager;

	@Inject
	private ChatboxPanelManager chatboxPanelManager;

	@Inject
	private BankHighlightSearchConfig config;

	@Inject
	private BankHighlightOverlay overlay;

	private volatile Set<Integer> matches = Collections.emptySet();

	@Getter
	private volatile long searchTime;

	private volatile boolean pendingScroll;
	private volatile boolean searchSubmitted;
	private String lastQuery = "";
	private ChatboxTextInput searchInput;

	private final HotkeyListener hotkeyListener = new HotkeyListener(() -> config.searchKeybind())
	{
		@Override
		public void hotkeyPressed()
		{
			clientThread.invoke(BankHighlightSearchPlugin.this::openSearch);
		}
	};

	@Provides
	BankHighlightSearchConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(BankHighlightSearchConfig.class);
	}

	@Override
	protected void startUp()
	{
		overlayManager.add(overlay);
		keyManager.registerKeyListener(hotkeyListener);
	}

	@Override
	protected void shutDown()
	{
		keyManager.unregisterKeyListener(hotkeyListener);
		overlayManager.remove(overlay);
		matches = Collections.emptySet();
		pendingScroll = false;
		clientThread.invoke(() ->
		{
			if (searchInput != null && chatboxPanelManager.getCurrentInput() == searchInput)
			{
				chatboxPanelManager.close();
				searchInput = null;
			}
		});
	}

	boolean isMatched(int itemId)
	{
		return matches.contains(itemId);
	}

	// client thread
	private void openSearch()
	{
		if (searchInput != null)
		{
			// prompt already open: clear it for a fresh query (value() redraws the open widget)
			searchInput.value("");
			updateMatches("");
			return;
		}

		final Widget bankItems = client.getWidget(InterfaceID.Bankmain.ITEMS);
		if (bankItems == null || bankItems.isHidden())
		{
			return; // bank not open
		}
		if (client.getVarcIntValue(VarClientID.MESLAYERMODE) != 0)
		{
			return; // another chatbox input is active (chat, native search, ...)
		}

		matches = Collections.emptySet();
		lastQuery = "";
		searchSubmitted = false;

		searchInput = chatboxPanelManager.openTextInput("Highlight search:")
			.onChanged(q -> clientThread.invoke(() -> updateMatches(q)))
			.onDone((Consumer<String>) q ->
			{
				searchSubmitted = true;
				clientThread.invoke(() ->
				{
					updateMatches(q);
					goToAllTabAndScroll();
				});
			})
			.onClose(() ->
			{
				searchInput = null;
				if (!searchSubmitted)
				{
					matches = Collections.emptySet();
				}
			})
			.build();
	}

	// client thread
	private void updateMatches(String query)
	{
		lastQuery = query == null ? "" : query;
		matches = computeMatches(lastQuery);
		searchTime = System.currentTimeMillis();
	}

	// client thread; recompute without restarting the blink animation
	private void refreshMatches()
	{
		matches = computeMatches(lastQuery);
	}

	// client thread
	private Set<Integer> computeMatches(String query)
	{
		final String q = query.trim();
		if (q.isEmpty())
		{
			return Collections.emptySet();
		}

		final ItemContainer bank = client.getItemContainer(InventoryID.BANK);
		if (bank == null)
		{
			return matches; // container unavailable; keep current highlights
		}

		final List<SearchMatcher.BankItem> items = new ArrayList<>();
		for (Item item : bank.getItems())
		{
			final int id = item.getId();
			if (id <= 0)
			{
				continue;
			}
			final ItemComposition comp = itemManager.getItemComposition(id);
			if (comp.getPlaceholderTemplateId() != -1 && !config.highlightPlaceholders())
			{
				continue;
			}
			items.add(new SearchMatcher.BankItem(id, comp.getName()));
		}

		return SearchMatcher.match(items, q, config.includeVariations(), id -> ItemVariationMapping.map(itemManager.canonicalize(id)));
	}

	// client thread
	private void goToAllTabAndScroll()
	{
		if (matches.isEmpty())
		{
			return;
		}

		// closing the potion store via its button is required before switching tabs;
		// leaving it open in the background breaks deposits (see core TabInterface).
		// run the button's own onOp clientscript rather than client.menuAction, which the
		// plugin hub disallows; this mirrors the getOnInvTransmitListener+runScript path below
		if (client.getVarbitValue(VarbitID.BANK_CURRENTTAB) == POTIONSTORE_TAB)
		{
			final Widget potionStoreButton = client.getWidget(InterfaceID.Bankmain.POTIONSTORE_BUTTON);
			if (potionStoreButton != null && potionStoreButton.getOnOpListener() != null)
			{
				client.runScript(potionStoreButton.getOnOpListener());
			}
		}

		if (client.getVarbitValue(VarbitID.BANK_CURRENTTAB) != 0)
		{
			client.setVarbit(VarbitID.BANK_CURRENTTAB, 0);
		}

		final Widget bankItems = client.getWidget(InterfaceID.Bankmain.ITEMS);
		if (bankItems == null)
		{
			return;
		}

		final Object[] buildArgs = bankItems.getOnInvTransmitListener();
		if (buildArgs == null)
		{
			return;
		}

		// rebuild the bank the same way BankSearch.layoutBank() does; BANKMAIN_FINISHBUILDING
		// fires during this call and onScriptPostFired performs the scroll
		pendingScroll = true;
		client.runScript(buildArgs);
	}

	@Subscribe
	public void onMenuEntryAdded(MenuEntryAdded event)
	{
		if (event.getActionParam1() == InterfaceID.Bankmain.SEARCH
			&& event.getOption().equals("Search"))
		{
			client.createMenuEntry(-1)
				.setOption("Highlight search")
				.setTarget(event.getTarget())
				.setType(MenuAction.RUNELITE)
				.onClick(e -> openSearch());
		}
	}

	@Subscribe
	public void onScriptPostFired(ScriptPostFired event)
	{
		if (event.getScriptId() == ScriptID.BANKMAIN_FINISHBUILDING && pendingScroll)
		{
			pendingScroll = false;
			// defer: runScript is not reentrant and BANKMAIN_FINISHBUILDING fires nested
			// inside bankmain_build; scroll after all scripts for this tick finish
			clientThread.invokeAtTickEnd(this::scrollToMatches);
		}
	}

	@Subscribe
	public void onItemContainerChanged(ItemContainerChanged event)
	{
		if (event.getContainerId() == InventoryID.BANK && !matches.isEmpty())
		{
			refreshMatches();
		}
	}

	// runs at tick end on the client thread; scrolls so the densest cluster of matches is visible
	private void scrollToMatches()
	{
		final Widget bankItems = client.getWidget(InterfaceID.Bankmain.ITEMS);
		if (bankItems == null || matches.isEmpty())
		{
			return;
		}

		final List<Integer> centers = new ArrayList<>();
		for (Widget w : bankItems.getDynamicChildren())
		{
			if (!w.isSelfHidden() && matches.contains(w.getItemId()))
			{
				centers.add(w.getRelativeY() + w.getHeight() / 2);
			}
		}

		final int scrollY = ScrollCalculator.densestClusterScrollY(centers, bankItems.getHeight(), bankItems.getScrollHeight());
		if (scrollY < 0)
		{
			return;
		}

		client.runScript(ScriptID.UPDATE_SCROLLBAR, InterfaceID.Bankmain.SCROLLBAR, InterfaceID.Bankmain.ITEMS, scrollY);
		client.setVarcIntValue(VarClientID.BANK_SCROLLPOS, scrollY);
	}

	@Subscribe
	public void onWidgetClosed(WidgetClosed event)
	{
		if (event.getGroupId() == InterfaceID.BANKMAIN && event.isUnload())
		{
			matches = Collections.emptySet();
			pendingScroll = false;
		}
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if (BankHighlightSearchConfig.GROUP.equals(event.getGroup()))
		{
			clientThread.invoke(() ->
			{
				overlay.invalidateGlowCache();
				refreshMatches();
			});
		}
	}
}

package com.bankhighlightsearch;

import lombok.AllArgsConstructor;

@AllArgsConstructor
public enum HighlightStyle
{
	ITEM_OUTLINE("Item outline"),
	FEATHERED_PULSE("Feathered pulse"),
	ITEM_OUTLINE_AND_FILL("Outline + fill"),
	BOX("Box border"),
	UNDERLINE("Underline"),
	FILL("Filled box");

	private final String name;

	@Override
	public String toString()
	{
		return name;
	}
}

package com.bankhighlightsearch;

import java.util.ArrayList;
import java.util.Collection;
import java.util.Collections;
import java.util.List;

final class ScrollCalculator
{
	private ScrollCalculator()
	{
	}

	/**
	 * Picks the scroll position that makes the most matched items visible at once:
	 * a sliding window of the viewport height over the sorted item centers finds the
	 * densest cluster (ties go to the topmost), which is then centered in the viewport.
	 *
	 * @return scrollY clamped to [0, scrollHeight], or -1 when matchCenterYs is empty
	 */
	static int densestClusterScrollY(Collection<Integer> matchCenterYs, int viewportHeight, int scrollHeight)
	{
		if (matchCenterYs.isEmpty())
		{
			return -1;
		}

		final List<Integer> centers = new ArrayList<>(matchCenterYs);
		Collections.sort(centers);

		int bestCount = 0;
		int bestFirst = 0;
		int bestLast = 0;
		int j = 0;
		for (int i = 0; i < centers.size(); i++)
		{
			if (j < i)
			{
				j = i;
			}
			while (j + 1 < centers.size() && centers.get(j + 1) - centers.get(i) <= viewportHeight)
			{
				j++;
			}
			final int count = j - i + 1;
			if (count > bestCount)
			{
				bestCount = count;
				bestFirst = i;
				bestLast = j;
			}
		}

		final int clusterMid = (centers.get(bestFirst) + centers.get(bestLast)) / 2;
		return Math.max(0, Math.min(scrollHeight, clusterMid - viewportHeight / 2));
	}
}

package com.bankhighlightsearch;

import java.util.Collection;
import java.util.HashSet;
import java.util.Locale;
import java.util.Set;
import java.util.function.IntUnaryOperator;
import lombok.Value;

final class SearchMatcher
{
	@Value
	static class BankItem
	{
		int id;
		String name;
	}

	private SearchMatcher()
	{
	}

	/**
	 * @param variationBase maps an item id to its variation-group base id
	 *                      (pass ItemVariationMapping::map in production)
	 */
	static Set<Integer> match(Collection<BankItem> items, String query, boolean includeVariations, IntUnaryOperator variationBase)
	{
		final String q = query.trim().toLowerCase(Locale.ROOT);
		final Set<Integer> matched = new HashSet<>();
		if (q.isEmpty())
		{
			return matched;
		}

		final Set<Integer> matchedBases = new HashSet<>();
		for (BankItem item : items)
		{
			if (item.getName().toLowerCase(Locale.ROOT).contains(q))
			{
				matched.add(item.getId());
				if (includeVariations)
				{
					matchedBases.add(variationBase.applyAsInt(item.getId()));
				}
			}
		}

		if (includeVariations)
		{
			for (BankItem item : items)
			{
				if (!matched.contains(item.getId()) && matchedBases.contains(variationBase.applyAsInt(item.getId())))
				{
					matched.add(item.getId());
				}
			}
		}

		return matched;
	}
}

